Code.Terraform:
resource "tfe_variable" "aws_auth" {
  key          = "TFC_AWS_PROVIDER_AUTH"
  value        = "true"
  category     = "env"
  workspace_id = tfe_workspace.prod.id
}

resource "tfe_variable" "aws_role" {
  key          = "TFC_AWS_RUN_ROLE_ARN"
  value        = aws_iam_role.tfc_run.arn
  category     = "env"
  workspace_id = tfe_workspace.prod.id
}
